// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 1, depositAmount);
        minSum = bound(minSum, 0, depositAmount);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xcafe));
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect with collectAmount (may revert, we only care about successful calls)
        vm.prank(caller);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // If the call succeeded, the balance must remain unchanged (bug: no subtraction)
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore, "Balance changed after Collect");
        } else {
            // if it reverted, no state change, so assert on revert happens implicitly
            // For the rule to hold universally, we must still check that balance didn't change
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore, "Balance changed despite revert");
        }
    }
}

