pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 am, uint256 depositVal, uint256 minSum) public {
        vm.assume(caller != address(0));
        vm.assume(depositVal < type(uint256).max / 2);
        vm.assume(am <= depositVal);

        c.SetMinSum(minSum);
        c.SetLogFile(address(1)); // dummy log, but we won't rely on its state
        c.Initialized();

        vm.deal(caller, depositVal);
        vm.prank(caller);
        c.Deposit{value: depositVal}();

        uint256 initialBal = address(c).balance;

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        if (success) {
            // After a successful Collect, the contract's ether balance decreased by exactly am
            assertTrue(address(c).balance == initialBal - am);
        } else {
            // On revert, the balance is unchanged
            assertTrue(address(c).balance == initialBal);
        }
    }
}

