import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Setup: initialize the contract, set MinSum, and fund caller
        vm.assume(caller != address(0));
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead)); // dummy log address to avoid revert in AddMessage (the actual Log doesn't fail)
        c.Initialized();
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Bound collectAmount to be <= balance and <= depositAmount to satisfy the condition
        vm.assume(collectAmount <= balanceBefore);
        vm.assume(collectAmount <= depositAmount);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        vm.assume(success); // Ensure the call succeeded

        // Assert: caller's balance remains unchanged
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceBefore == balanceAfter, "Balance should not change");
    }
}

