pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 amt) public {
        vm.assume(caller != address(0));
        vm.assume(amt > 0);
        vm.assume(initialBalance >= amt);
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Ensure MinSum is set to 0 so the condition balances[msg.sender] >= MinSum is always true
        c.SetMinSum(0);
        // Ensure initialized is true so that SetMinSum cannot be called again
        c.Initialized();

        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amt));
        uint256 balanceAfter = c.balances(caller);

        // General rule: if the call succeeded, balance decreased exactly by amt and Log was updated;
        // if the call reverted, balance should be unchanged (since revert should roll back the subtraction).
        // But because the buggy version subtracts before the call and does not revert on failure,
        // the balance decreases even on failure. So we check: balanceAfter >= balanceBefore - (success ? amt : 0).
        // However, to make a single assertion that catches the bug, we use: 
        // (success || balanceAfter == balanceBefore) — but that's too specific. 
        // Better: In the correct version, if the call failed (revert), the state is rolled back, so balanceAfter == balanceBefore.
        // In the buggy version, the balanceAfter is decreased even on failure.
        // So we assert: if (!success) then balanceAfter == balanceBefore.
        // This passes on C and fails on M because M does not revert on failure.
        emit log_uint(balanceAfter);
        emit log_uint(balanceBefore);
        assertTrue(!success || balanceAfter == balanceBefore - amt);
        if (!success) {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

