pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound values to reasonable ranges
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(depositAmount <= type(uint256).max / 4);
        vm.assume(collectAmount <= type(uint256).max / 4);

        // Setup: initialize contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller
        vm.deal(caller, depositAmount);

        // Deposit from caller
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Get the caller's balance before Collect
        uint256 callerBalanceBefore = c.balances(caller);

        // Also get some other address's balance (randomly selected)
        address other = address(0xdeadbeef);
        uint256 otherBalanceBefore = c.balances(other);

        // Perform Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get balances after Collect
        uint256 callerBalanceAfter = c.balances(caller);
        uint256 otherBalanceAfter = c.balances(other);

        // General rule: all balances stay the same if Collect reverted (call failed)
        bool reverted = !success;
        assertTrue(
            !reverted || 
            (callerBalanceAfter == callerBalanceBefore && otherBalanceAfter == otherBalanceBefore),
            "Balances changed even though Collect reverted"
        );
    }
}

