pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        // Set MinSum once (only if not initialized)
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller with enough Ether to deposit and cover gas
        vm.deal(caller, depositAmount + 1 ether);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 oldBalance = c.balances(caller);

        // Record the log count before (LogFile has no public getter for count, so we use a proxy: we can't check log, but we can check if the call reverts)
        // For this rule, we'll check if the Collect reverts or not
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 newBalance = c.balances(caller);

        // The rule: if the call succeeded (i.e., no revert), then balance decreased by collectAmount; otherwise balance stays same
        if (success) {
            assertTrue(newBalance == oldBalance - collectAmount, "Balance should decrease by collectAmount on success");
        } else {
            assertTrue(newBalance == oldBalance, "Balance should stay same on revert");
        }
    }
}

