pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint minSum, uint amount, uint initialBalance, uint callerBalance) public {
        // Bound inputs to avoid overflows and keep balances reasonable
        minSum = bound(minSum, 0, 1000000);
        amount = bound(amount, 0, 1000000);
        initialBalance = bound(initialBalance, 0, 1000000);
        callerBalance = bound(callerBalance, 0, 1000000);

        // Setup: initialize contract with MinSum and fund contract
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(address(c), initialBalance);

        // Fund caller if they are not the zero address
        vm.assume(caller != address(0));
        vm.deal(caller, callerBalance);

        // Record balances before Collect
        uint callerBalBefore = c.balances(caller);
        uint contractBalBefore = address(c).balance;

        // Optionally deposit to caller's balance to satisfy MinSum
        if (callerBalBefore < minSum) {
            vm.prank(caller);
            c.Deposit{value: minSum - callerBalBefore}();
            callerBalBefore = minSum;
        }

        // Ensure contract has enough ether to possibly pay out
        vm.assume(contractBalBefore >= amount);

        // Call Collect and check if it would revert due to failed call (e.g., caller is a contract that rejects)
        bool collectReverted;
        try c.Collect(amount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint callerBalAfter = c.balances(caller);
        uint contractBalAfter = address(c).balance;

        // General rule: If the call reverted, the total net ether (caller balance + contract balance) must remain unchanged
        // because no ether should have moved out of the contract and caller's balance should not have been decremented.
        if (collectReverted) {
            assertTrue(callerBalBefore + contractBalBefore == callerBalAfter + contractBalAfter, "Bug: balance sum changed on revert");
        }
    }
}

