pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 depositAmt, uint256 collectAmt) public {
        // Bound inputs to reasonable ranges
        depositAmt = bound(depositAmt, 1 ether, 1000 ether);
        collectAmt = bound(collectAmt, 0, depositAmt);

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit from user
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Deposit{value: depositAmt}();

        // Compute total balance before Collect
        // We need to read balances of all addresses that could have a balance.
        // Since we only have user as a depositor, we read user and the contract itself
        // (though contract balance is not summed, as the mapping is separate).
        // Actually, the total balance in the mapping is just user's balance.
        uint256 totalBefore = c.balances(user);

        // Call Collect
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // Compute total balance after Collect (only if success, else revert test - but we want general rule)
        if (success) {
            uint256 totalAfter = c.balances(user);
            // General rule: total balance (sum of all balances) does not increase
            // Since only user has a balance, this is just user's balance
            assertTrue(totalAfter <= totalBefore);
        }
    }
}

