pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 am, uint256 depositAmount) public {
        // Bound parameters to reasonable ranges
        minSum = bound(minSum, 0, 1e30);
        am = bound(am, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);

        // Setup: initialize the contract with minSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit from the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record caller's balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect
        bool reverted;
        vm.prank(caller);
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final balance of the caller
        uint256 balanceAfter = c.balances(caller);

        // General rule: 
        // If Collect did not revert, then balanceAfter <= balanceBefore - min(am, balanceBefore) when balanceBefore >= minSum? 
        // Actually the invariant is: if Collect succeeded, then balanceAfter == balanceBefore - am (by construction) 
        // AND the original contract requires balanceBefore >= minSum. So the bug means that when balanceBefore == minSum, 
        // the buggy contract reverts, while the reference succeeds. 
        // The key difference is: in reference, Collect succeeds when balanceBefore >= minSum && balanceBefore >= am. 
        // In the buggy version, it fails when balanceBefore == minSum (even if >= am). 
        // So a suitable rule: the caller's balance after Collect is never >= minSum when the call would have succeeded in reference but fails in buggy.
        // Actually simpler: for any am such that balanceBefore >= minSum and balanceBefore >= am, the reference contract allows Collect to succeed.
        // So we can assert: if balanceBefore >= minSum && balanceBefore >= am, then Collect must NOT revert.
        // That property holds on reference (because condition true), and fails on buggy (when balanceBefore == minSum, it reverts).
        if (balanceBefore >= minSum && balanceBefore >= am) {
            assertTrue(!reverted, "Collect should not revert when balance >= minSum and balance >= am");
        }
    }
}

