        vm.assume(minSum <= type(uint128).max);
        vm.assume(depositBefore <= type(uint128).max);
        vm.assume(collectAmount <= type(uint128).max);
        // Ensure deposit is enough to make balance >= MinSum before Collect
        vm.assume(depositBefore >= minSum);
