        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositBefore);
        vm.prank(caller);
        c.Deposit{value: depositBefore}();

        // Record pre-balance and MinSum to compute expected invariant
        uint256 preBalance = c.balances(caller);

        bool collectReverted;
        // Attempt Collect
        vm.prank(caller);
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // The invariant: If Collect succeeded, then preBalance >= minSum (by assumption) and
        // after Collect, the new balance = preBalance - collectAmount.
        // For the reference: if preBalance >= minSum, then after Collect the balance must be < minSum
        // because Collect subtracts collectAmount > 0 and preBalance - collectAmount < minSum?
        // Actually the bug is that reference allows balance == minSum to collect (reverts? no, reference collects if >= minSum)
        // Wait: In the reference, if preBalance == minSum, then Collect succeeds and new balance = minSum - collectAmount < minSum.
        // In the buggy version, if preBalance == minSum, then preBalance > minSum is false, so Collect does nothing (no revert, just skips).
        // So the difference is: when preBalance == minSum and collectAmount <= preBalance,
        // reference reduces balance to minSum - collectAmount, buggy leaves balance at minSum.
        // So the rule: after a Collect call, if preBalance >= minSum and preBalance >= collectAmount, then
        // the balance is strictly less than minSum if the call succeeded in reference, but could be exactly minSum in buggy.
        // But we need a general rule that always holds on reference and sometimes fails on buggy.
        // Since we parameterize preBalance by depositBefore, we can assert:
        // If Collect did not revert, then the caller's balance after is strictly less than minSum.
        // In reference: when preBalance >= minSum, Collect always succeeds (since non-reverting when condition true) and balance becomes preBalance - collectAmount < preBalance <= ? Actually if preBalance == minSum, then new balance = minSum - collectAmount < minSum.
        // In buggy: when preBalance == minSum, Collect does nothing (no revert), so balance stays at minSum, which is NOT < minSum.
        if (!collectReverted) {
            uint256 postBalance = c.balances(caller);
            assertTrue(postBalance < minSum, "After non-reverting Collect, balance should be < MinSum");
        }
    }
}

