        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit so sender has balance
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Try Collect
        vm.prank(sender);
        (bool callSuccess,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: if Collect succeeded, then sender's balance BEFORE was >= MinSum
        assertTrue(!callSuccess || c.balances(sender) >= minSum);
    }
}

