// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 minSum, uint256 deposit, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(deposit <= type(uint256).max - amount);

        // Initialize contract
        c.SetMinSum(bound(minSum, 0, type(uint256).max / 2));
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit some balance for sender
        vm.deal(sender, deposit);
        vm.prank(sender);
        c.Deposit{value: deposit}();

        // Record sender's balance before Collect
        uint256 balanceBefore = sender.balance;

        // Call Collect(amount)
        bool reverted;
        try c.Collect(bound(amount, 0, deposit)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: after Collect, sender's balance is initial balance + amount if reverted, else unchanged
        if (reverted) {
            assertTrue(sender.balance == balanceBefore + amount);
        } else {
            assertTrue(sender.balance == balanceBefore);
        }
    }
}
